TEMPLATE = """<?xml version="1.0" encoding="utf-8"?>
<!-- Material Icons "{name}" (Apache-2.0), filled, 24 dp (taste D23: standard icon set; tools/make_icons.py). -->
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="24dp"
    android:height="24dp"
    android:viewportWidth="24"
    android:viewportHeight="24">
    <path
        android:fillColor="#FFFFFFFF"
        android:pathData="{d}" />
</vector>
"""

if __name__ == "__main__":
    out = os.path.join("app", "src", "main", "res", "drawable")
    for f in os.listdir(out):
        if f.startswith("ic_") and f != "ic_launcher_foreground.xml":
            os.remove(os.path.join(out, f))
    for name, d in ICONS.items():
        with open(os.path.join(out, "ic_" + name + ".xml"), "w", encoding="utf-8") as fh:
            fh.write(TEMPLATE.format(name=name, d=d))
    print(len(ICONS), "icons")
